-- November 2026: two supplied audiobooks. Introductions are embedded in the first audio track.
-- Run only after all five audio objects pass upload-verification.json.
begin;
insert into public.audiobooks (slug, title, author, narrator, category, description, total_duration_seconds, cover_from, cover_via, cover_to, vibe, is_published)
select slug, title, author, narrator, category, description, total_duration_seconds, cover_from, cover_via, cover_to, vibe, is_published
from jsonb_to_recordset($books$[{"slug": "telegrafi-dello-stato-sezione-femminile", "title": "Telegrafi dello Stato (Sezione femminile)", "author": "Matilde Serao", "narrator": "Antonella Civale", "category": "Narrativa", "description": "Nella Napoli di fine Ottocento, le giovani impiegate della sezione femminile dei Telegrafi dello Stato affrontano turni estenuanti, salari bassi e rigide gerarchie. Tra attese, amicizie e desideri di autonomia, Matilde Serao racconta il lavoro e la vita quotidiana di donne sospese fra bisogno di indipendenza e aspettative sociali.", "vibe": "Lavoro femminile, Napoli, desiderio di autonomia", "cover_from": "#6b3b17", "cover_via": "#c89144", "cover_to": "#28180d", "is_published": true, "total_duration_seconds": 6231}, {"slug": "il-voto-alle-donne-e-donne-della-costituente", "title": "Il voto alle donne e donne della Costituente", "author": "Paola Gaiotti de Biase", "narrator": "Paola Giglio", "category": "Saggistica", "description": "Una riflessione storica sull’ingresso delle donne nella cittadinanza politica italiana: dalla conquista del diritto di voto al contributo delle elette all’Assemblea Costituente. Paola Gaiotti de Biase ripercorre il significato di questa svolta e il riconoscimento della presenza femminile nella storia della democrazia italiana.", "vibe": "Suffragio femminile, cittadinanza, memoria della Costituente", "cover_from": "#154e59", "cover_via": "#3e93a0", "cover_to": "#0a2933", "is_published": true, "total_duration_seconds": 1122}]$books$::jsonb)
as b(slug text, title text, author text, narrator text, category text, description text,
     total_duration_seconds integer, cover_from text, cover_via text, cover_to text, vibe text, is_published boolean)
on conflict (slug) do update set
title = excluded.title, author = excluded.author, narrator = excluded.narrator, category = excluded.category, description = excluded.description, total_duration_seconds = excluded.total_duration_seconds, cover_from = excluded.cover_from, cover_via = excluded.cover_via, cover_to = excluded.cover_to, vibe = excluded.vibe, is_published = excluded.is_published;
insert into public.chapters (book_id, slug, chapter_index, title, duration_seconds, audio_url)
select b.id, c.chapter_slug, c.chapter_index, c.chapter_title, c.duration_seconds, c.audio_url
from jsonb_to_recordset($chapters$[{"book_slug": "telegrafi-dello-stato-sezione-femminile", "chapter_index": 1, "chapter_slug": "capitolo-i", "chapter_title": "I", "duration_seconds": 1664, "r2_key": "telegrafi-dello-stato-sezione-femminile/01-capitolo-i.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/telegrafi-dello-stato-sezione-femminile/01-capitolo-i.wav"}, {"book_slug": "telegrafi-dello-stato-sezione-femminile", "chapter_index": 2, "chapter_slug": "capitolo-ii", "chapter_title": "II", "duration_seconds": 2633, "r2_key": "telegrafi-dello-stato-sezione-femminile/02-capitolo-ii.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/telegrafi-dello-stato-sezione-femminile/02-capitolo-ii.wav"}, {"book_slug": "telegrafi-dello-stato-sezione-femminile", "chapter_index": 3, "chapter_slug": "capitolo-iii", "chapter_title": "III", "duration_seconds": 922, "r2_key": "telegrafi-dello-stato-sezione-femminile/03-capitolo-iii.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/telegrafi-dello-stato-sezione-femminile/03-capitolo-iii.wav"}, {"book_slug": "telegrafi-dello-stato-sezione-femminile", "chapter_index": 4, "chapter_slug": "capitolo-iv", "chapter_title": "IV", "duration_seconds": 1012, "r2_key": "telegrafi-dello-stato-sezione-femminile/04-capitolo-iv.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/telegrafi-dello-stato-sezione-femminile/04-capitolo-iv.wav"}, {"book_slug": "il-voto-alle-donne-e-donne-della-costituente", "chapter_index": 1, "chapter_slug": "lettura-integrale", "chapter_title": "Il voto alle donne e donne della Costituente", "duration_seconds": 1122, "r2_key": "il-voto-alle-donne-e-donne-della-costituente/01-lettura-integrale.wav", "audio_url": "https://pub-5c8f826260ec4bc4a78e9186bb598e0e.r2.dev/il-voto-alle-donne-e-donne-della-costituente/01-lettura-integrale.wav"}]$chapters$::jsonb)
as c(book_slug text, chapter_index integer, chapter_slug text, chapter_title text, duration_seconds integer, r2_key text, audio_url text)
join public.audiobooks b on b.slug = c.book_slug
on conflict (book_id, slug) do update set chapter_index=excluded.chapter_index, title=excluded.title,
duration_seconds=excluded.duration_seconds, audio_url=excluded.audio_url;
commit;
select b.slug, b.title, b.category, b.narrator, b.is_published, b.total_duration_seconds,
       count(c.id) as tracks, array_agg(c.title order by c.chapter_index) as ordered_chapters
from public.audiobooks b join public.chapters c on c.book_id=b.id
where b.slug in ('telegrafi-dello-stato-sezione-femminile','il-voto-alle-donne-e-donne-della-costituente')
group by b.id order by b.slug;
